import{_ as a,o as t,c as o,ag as i}from"./chunks/framework.Cyu1VozZ.js";const c=JSON.parse('{"title":"Viewing Images","description":"","frontmatter":{},"headers":[],"relativePath":"pdf/viewing-images.md","filePath":"pdf/viewing-images.md"}'),n={name:"pdf/viewing-images.md"};function s(r,e,l,h,d,g){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="viewing-images" tabindex="-1">Viewing Images <a class="header-anchor" href="#viewing-images" aria-label="Permalink to &quot;Viewing Images&quot;">​</a></h1><p>Wafflebase stores and displays <strong>image files</strong> alongside your sheets, docs, slides, notes, and PDFs. Like a PDF, an image is a <em>view-only</em> document type — you upload the original file and view it in the browser; the image itself is never edited.</p><p>Supported formats are <strong>PNG, JPEG, GIF, and WebP</strong>, up to <strong>25 MB</strong> per file.</p><h2 id="upload-an-image" tabindex="-1">Upload an image <a class="header-anchor" href="#upload-an-image" aria-label="Permalink to &quot;Upload an image&quot;">​</a></h2><ol><li>Open your workspace</li><li>Click the <strong>New</strong> dropdown button</li><li>Select <strong>Upload files…</strong></li><li>Choose one or more image files from your computer</li></ol><p>Wafflebase reads the file extension and creates an image document. It appears in your workspace document list with a thumbnail, and its title defaults to the file name (which you can rename). A panel in the bottom-right tracks the upload and offers an <strong>Open</strong> link once it finishes.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You can also <strong>drag files straight onto the documents list</strong> to upload several at once. Every file goes through the same door: images, PDFs, spreadsheets, documents, and presentations each become the matching document type, and a file Wafflebase has no viewer for is stored as-is — you can download it again from its header. See <a href="/docs/guide/import-export.html">Import &amp; Export</a> for the full list.</p></div><h2 id="view-an-image" tabindex="-1">View an image <a class="header-anchor" href="#view-an-image" aria-label="Permalink to &quot;View an image&quot;">​</a></h2><p>The viewer centers the image and fits it to your window. A spinner shows while the file downloads on first open.</p><ul><li><strong>Zoom</strong> — a small toolbar sits at the bottom of the viewer, with the current zoom shown as a percentage between the two buttons. Each click steps 25%, from <strong>25%</strong> at the smallest to <strong>500%</strong> at the largest. Opening another image starts again at 100%.</li><li><strong>Previous / Next</strong> — arrow buttons float over the left and right edges of the image and move to the neighbouring image, so you can page through a set without going back to the list. <code>←</code> and <code>→</code> do the same from the keyboard. Each arrow only appears when there is something on that side.</li><li><strong>Esc</strong> — leaves the viewer for the documents list you came from.</li><li><strong>Download</strong> — the download icon in the page <em>header</em> (beside <strong>Share</strong>) saves the original file to your computer.</li></ul><div class="tip custom-block"><p class="custom-block-title">Prev/Next stay inside one folder</p><p>The neighbours are the other images in the <strong>same folder</strong> of the same workspace, ordered by title — not every image in the workspace. An image at the workspace root pages through the other root images, never into a folder.</p></div><h2 id="rename-an-image" tabindex="-1">Rename an image <a class="header-anchor" href="#rename-an-image" aria-label="Permalink to &quot;Rename an image&quot;">​</a></h2><p>Click the title in the header to rename the document. The change is reflected in your workspace list right away.</p><h2 id="share-an-image" tabindex="-1">Share an image <a class="header-anchor" href="#share-an-image" aria-label="Permalink to &quot;Share an image&quot;">​</a></h2><p>Click <strong>Share</strong> in the header to create a link, the same way you would for any other document — see <a href="/docs/guide/collaboration.html">Collaboration &amp; Sharing</a>.</p><p>Someone opening that link sees the image and can zoom and download it, but gets <strong>no previous/next arrows and no Esc shortcut</strong>: both need the workspace&#39;s document list, which a share link doesn&#39;t grant access to. A share link is one image, not a tour of the folder it lives in.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Images are read-only. To change one, edit it elsewhere and upload the new version.</p></div>',17)])])}const p=a(n,[["render",s]]);export{c as __pageData,p as default};
